function translated(text){if(language!=='en')return text;let out=text;for(const [it,en] of translationEntries)out=out.split(it).join(en);return out}
const originalText=new WeakMap();
function localize(root=document){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!node.parentElement||['SCRIPT','STYLE'].includes(node.parentElement.tagName))continue;if(!originalText.has(node))originalText.set(node,node.nodeValue);node.nodeValue=translated(originalText.get(node))}const attrs=['placeholder','aria-label','title'];for(const el of (root.nodeType===1?[root,...root.querySelectorAll('*')]:root.querySelectorAll('*')))for(const attr of attrs)if(el.hasAttribute(attr)){const key=`source${attr.replace(/(^|-)([a-z])/g,(_,a,c)=>c.toUpperCase())}`;if(!el.dataset[key])el.dataset[key]=el.getAttribute(attr);el.setAttribute(attr,translated(el.dataset[key]))}}
function setLanguage(next){language=next;localStorage.setItem('sleepResetLanguage',next);document.documentElement.lang=next==='en'?'en':'it';document.title=next==='en'?'Natural Sleep — Sleep isn’t chased. It’s prepared.':'Sonno Naturale — Il sonno non si cerca. Si prepara.';const description=$('meta[name="description"]');if(description)description.content=next==='en'?'Your Natural Sleep journey, one step at a time.':'Il tuo percorso Sonno Naturale, un passo alla volta.';const manifest=$('#appManifest');if(manifest)manifest.href=next==='en'?'./manifest-en.webmanifest':'./manifest.webmanifest';$$('.language-toggle [data-lang]').forEach(el=>el.classList.toggle('active',el.dataset.lang===next));$$('.language-toggle').forEach(el=>el.setAttribute('aria-label',next==='en'?'Switch to Italian':'Passa alla lingua inglese'));localize(document);$$('.brand-mark').forEach(el=>{if(el.firstChild)el.firstChild.nodeValue=next==='en'?'NS':'SN'})}
