function toast(text){const el=$('#toast');el.textContent=translated(text);el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function showModal(html){$('#modalContent').innerHTML=html;localize($('#modalContent'));$('#modalBackdrop').hidden=false;document.body.style.overflow='hidden';$('#modalClose').focus()}
function closeModal(){$('#modalBackdrop').hidden=true;document.body.style.overflow=''}
$('#modalClose').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modalBackdrop').hidden)closeModal()});
function renderTasks(){if(liveMode){const selected=language==='en'?'title_en':'title_it',description=language==='en'?'description_en':'description_it';$('#taskList').innerHTML=liveGoals.length?liveGoals.map((g,i)=>{const done=liveCompletions.has(g.id);return `<button class="task-card ${done?'done':''}" data-live-goal="${escapeHtml(g.id)}" aria-pressed="${done}"><span class="task-check">${done?'✓':''}</span><span class="task-copy"><strong>${escapeHtml(g[selected]||g.title_it)}</strong><span>${done?(language==='en'?'Completed · ':'Completato · '):(g[description]||g.description_it||'')}</span></span><span class="task-icon">${i%2?'◷':'✳'}</span></button>`}).join(''):`<div class="empty-state"><span>✳</span><strong>${language==='en'?'Your coach will add your first goals here.':'Il tuo coach aggiungerà qui i tuoi primi obiettivi.'}</strong><small>${language==='en'?'Your personal plan will appear when it is ready.':'Il tuo piano personalizzato comparirà qui appena pronto.'}</small></div>`;const count=liveCompletions.size,total=liveGoals.length;$('#taskCount').textContent=language==='en'?`${count} of ${total} completed`:`${count} di ${total} completati`;$('#completedStat').innerHTML=`${count} <small>/ ${total}</small>`;const pct=total?Math.round(count/total*100):0;$('#weekPercent').textContent=`${pct}%`;$('#weekRing').style.strokeDashoffset=100.5-(100.5*pct);localize($('#taskList'));return}let done=store.done||defaults.done;$('#taskList').innerHTML=tasks.map((t,i)=>`<button class="task-card ${done[i]?'done':''}" data-task="${i}" aria-pressed="${!!done[i]}"><span class="task-check">${done[i]?'✓':''}</span><span class="task-copy"><strong>${t.title}</strong><span>${done[i]?'Completato · ':''}${t.desc}</span></span><span class="task-icon">${t.icon}</span></button>`).join('');let count=done.filter(Boolean).length;$('#taskCount').textContent=`${count} di 3 fatti`;$('#completedStat').innerHTML=`${12+count-1} <small>/ 16</small>`;$('#weekPercent').textContent=`${Math.round((12+count-1)/16*100)}%`;$('#weekRing').style.strokeDashoffset=100.5-(100.5*(12+count-1)/16);localize($('#taskList'));localize($('#taskCount'));}
function renderWeeks(){if(liveMode){$('#weekList').innerHTML=weeks.map((w,i)=>`<article class="week-card"><div class="week-number">0${i+1}</div><div><div class="week-title">${w.title}</div><div class="week-description">${w.description}</div></div><div class="week-progress"><b>${language==='en'?'Protocol guide':'Guida protocollo'}</b><i><span style="width:0%"></span></i></div></article>`).join('');localize($('#weekList'));return}$('#weekList').innerHTML=weeks.map((w,i)=>`<article class="week-card ${i===1?'current':i===0?'complete':''}"><div class="week-number">${i===0?'✓':'0'+(i+1)}</div><div><div class="week-title">${w.title}${i===1?' <span class="status-pill good">IN CORSO</span>':''}</div><div class="week-description">${w.description}</div></div><div class="week-progress"><b>${w.progress}</b><i><span style="width:${w.pct}%"></span></i></div></article>`).join('');localize($('#weekList'))}
function durationLabel(row){if(!row.bed_time||!row.wake_time)return '—';const [bh,bm]=row.bed_time.slice(0,5).split(':').map(Number),[wh,wm]=row.wake_time.slice(0,5).split(':').map(Number),mins=(wh*60+wm-bh*60-bm+1440)%1440;return `${Math.floor(mins/60)} h ${String(mins%60).padStart(2,'0')} min`}
function dateLabel(value){const d=new Date(`${value}T12:00:00`);return d.toLocaleDateString(language==='en'?'en-GB':'it-IT',{day:'2-digit',month:'short'}).toUpperCase()}
function renderEntries(){if(liveMode){const rows=liveDiary;$('#diaryEntries').innerHTML=rows.map(r=>`<article class="entry-row"><span class="entry-day">${dateLabel(r.night_date)}</span><span class="entry-hours"><strong>${durationLabel(r)}</strong> ${language==='en'?'in bed · ':'a letto · '}<strong>${r.sleep_latency_minutes??'—'} min</strong> ${language==='en'?'to fall asleep':'per addormentarti'}</span><span class="entry-mood">${language==='en'?'Rating':'Valutazione'}: ${r.subjective_rating??'—'}/5</span></article>`).join('')||`<p class="subheading">${language==='en'?'No nights logged yet. Add your first entry whenever you like.':'Nessuna notte registrata. Aggiungi il primo appunto quando vuoi.'}</p>`;localize($('#diaryEntries'));return}let list=store.diary||[];$('#diaryEntries').innerHTML=list.map(d=>`<article class="entry-row"><span class="entry-day">${escapeHtml(d.date)}</span><span class="entry-hours"><strong>${escapeHtml(d.hours)}</strong> a letto · ${escapeHtml(d.sleep)} per addormentarti</span><span class="entry-mood">${escapeHtml(d.mood)}</span><button class="entry-link" data-entry="${escapeHtml(d.date)}">Dettagli ↗</button></article>`).join('')||'<p class="subheading">Nessuna notte registrata. Aggiungi il primo appunto quando vuoi.</p>';localize($('#diaryEntries'))}
function renderClients(){const list=$('#clientList');const source=liveMode?liveClients:clients;if(liveMode&&!source.length){list.innerHTML=`<div class="empty-state">${language==='en'?'No clients are assigned yet. Assign a verified client from Supabase to see their progress here.':'Non hai ancora clienti assegnati. Assegna un cliente verificato da Supabase per seguirne qui il percorso.'}</div>`;localize(list);return}list.innerHTML=source.map((c,i)=>`<button class="client-row" data-client="${i}"><span class="client-name"><span class="avatar avatar-small ${c.color||''}">${escapeHtml(c.initials||'')}</span><span><strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(c.phase||'')}</small></span></span><span class="client-progress"><i><b style="width:${c.progress||0}%"></b></i><small>${c.progress||0}%</small></span><span class="activity">${escapeHtml(c.activity||'')}</span><span><i class="status-pill ${c.kind||'good'}">${escapeHtml(c.status||'')}</i></span><span class="row-arrow">›</span></button>`).join('');localize($('#clientList'))}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function navigate(page){if($('#adminView').hidden===false){$('#adminView').hidden=true;$('#clientView').hidden=false;document.body.classList.remove('admin-mode');$('#adminSwitch').setAttribute('aria-pressed','false')}$$('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${page}`));$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));window.scrollTo({top:0,behavior:'smooth'})}
