async function toggleLiveGoal(goalId){try{if(liveCompletions.has(goalId)){await SRDB.remove('goal_completions',{goal_id:`eq.${goalId}`,client_id:`eq.${liveUser.id}`});liveCompletions.delete(goalId)}else{await SRDB.insert('goal_completions',{goal_id:goalId,client_id:liveUser.id});liveCompletions.add(goalId)}renderTasks();updateLiveClientDashboard()}catch(e){toast((language==='en'?'Could not save this goal: ':'Non sono riuscito a salvare l’obiettivo: ')+e.message)}}
$('#taskList').addEventListener('click',e=>{const live=e.target.closest('[data-live-goal]');if(live){toggleLiveGoal(live.dataset.liveGoal);return}const b=e.target.closest('[data-task]');if(!b)return;let i=+b.dataset.task;store.done[i]=!store.done[i];save();renderTasks();if(store.done[i])toast(['Luce del mattino: fatto!','Un passo alla volta. Ben fatto!','Hai chiuso la giornata con cura.'][i])});
$('#adminSwitch').addEventListener('click',()=>{let admin=$('#adminView').hidden;$('#adminView').hidden=!admin;$('#clientView').hidden=admin;document.body.classList.toggle('admin-mode',admin);$('#adminSwitch').setAttribute('aria-pressed',String(admin));if(admin){$$('.nav-link').forEach(b=>b.classList.remove('active'));window.scrollTo({top:0,behavior:'smooth'})}else navigate('oggi')});
function diaryForm(){showModal(`<p class="eyebrow">DIARIO DEL SONNO</p><h2 id="modalTitle">Com’è andata la notte?</h2><p>Annota quello che ricordi. Non serve essere precisi al minuto.</p><form id="diaryForm"><div class="form-grid"><div class="form-field full"><label for="nightDate">Data della notte</label><input id="nightDate" name="nightDate" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="form-field"><label for="bed">A che ora sei andata a letto?</label><input id="bed" name="bed" type="time" value="22:45" required></div><div class="form-field"><label for="wake">A che ora ti sei alzata?</label><input id="wake" name="wake" type="time" value="06:00" required></div><div class="form-field"><label for="fall">Minuti per addormentarti</label><input id="fall" name="fall" type="number" min="0" max="240" value="22"></div><div class="form-field"><label for="awakenings">Risvegli durante la notte</label><select id="awakenings" name="awakenings"><option>0</option><option selected>2</option><option>3</option><option>4 o più</option></select></div><div class="form-field full"><label for="mood">Come ti senti stamattina?</label><select id="mood" name="mood"><option>Molto bene</option><option selected>Abbastanza bene</option><option>Un po’ stanca</option><option>Stanca</option></select></div><div class="form-field full"><label for="notes">Un appunto (facoltativo)</label><textarea id="notes" name="notes" placeholder="C’è qualcosa che vuoi ricordare o condividere con Daniele?"></textarea></div></div><p class="form-hint">Queste note servono a osservare il tuo ritmo, non a valutare la qualità di una singola notte.</p><div class="modal-actions"><button type="button" class="secondary-btn" data-cancel>Annulla</button><button class="primary-btn">Salva la notte</button></div></form>`);$('#diaryForm').addEventListener('submit',async e=>{e.preventDefault();let f=new FormData(e.target);if(liveMode){const moodMap={'Molto bene':5,'Abbastanza bene':4,'Un po’ stanca':3,'Stanca':2,'Very good':5,'Fairly well':4,'A little tired':3,'Tired':2};try{await SRDB.upsert('sleep_entries',{client_id:liveUser.id,night_date:f.get('nightDate'),bed_time:f.get('bed'),wake_time:f.get('wake'),sleep_latency_minutes:Number(f.get('fall')||0),awakenings:Number(String(f.get('awakenings')).split(' ')[0])||0,subjective_rating:moodMap[f.get('mood')]||3,notes:f.get('notes')||''},'client_id,night_date');await loadLiveClientData();closeModal();toast(language==='en'?'Sleep diary saved.':'Notte salvata nel diario.')}catch(err){toast((language==='en'?'Could not save diary: ':'Non sono riuscito a salvare il diario: ')+err.message)}return}let date=new Date().toLocaleDateString('it-IT',{day:'2-digit',month:'short'}).toUpperCase(),bed=f.get('bed').split(':').map(Number),wake=f.get('wake').split(':').map(Number),duration=((wake[0]*60+wake[1])-(bed[0]*60+bed[1])+1440)%1440,hours=Math.floor(duration/60),mins=duration%60;store.diary.unshift({date,hours:`${hours} h ${String(mins).padStart(2,'0')} min`,sleep:`${f.get('fall')} min`,wake:`${f.get('awakenings')} ${f.get('awakenings')==='1'?'volta':'volte'}`,mood:f.get('mood'),notes:f.get('notes')});save();renderEntries();closeModal();toast('La tua notte è stata aggiunta al diario.')});$('[data-cancel]').onclick=closeModal}
$('#openDiary').onclick=diaryForm;$('#openDiary2').onclick=diaryForm;$('#openCoachNote').onclick=()=>showModal(`<p class="eyebrow">UN MESSAGGIO PER TE · IERI</p><h2 id="modalTitle">Un consiglio di Daniele</h2><div class="recommendation"><strong>✳ Un piccolo promemoria, Martina</strong><p>${escapeHtml(store.advice)}</p></div><p>Le indicazioni del percorso sono personalizzate e possono cambiare nel tempo. Se hai dubbi di salute, parlane con il tuo medico.</p><div class="modal-actions"><button class="primary-btn" data-cancel>Ho capito</button></div>`);$('#modalContent').addEventListener('click',e=>{if(e.target.closest('[data-cancel]'))closeModal()});
function openClient(c){let m=c.name==='Martina C.';showModal(`<p class="eyebrow">SCHEDA PERCORSO · ${escapeHtml(c.phase.toUpperCase())}</p><div class="client-detail-head"><div class="avatar ${c.color}">${c.initials}</div><div><h2 id="modalTitle">${escapeHtml(c.name)}</h2><p>Nel percorso da ${m?'10 novembre':'inizio novembre'} · Ultima attività ${escapeHtml(c.activity.toLowerCase())}</p></div></div><div class="detail-stats"><div class="detail-stat"><span>AVANZAMENTO</span><strong>${c.progress}%</strong></div><div class="detail-stat"><span>PASSI FATTI</span><strong>${m?'12':'9'} / 16</strong></div><div class="detail-stat"><span>EFFICIENZA</span><strong>${m?'82':'76'}%</strong></div></div><div class="recommendation"><strong>Ultimo appunto dal diario</strong><p>${m?'“La luce al mattino mi sta aiutando più di quanto pensassi.”':'Diario in attesa di aggiornamento. Un check-in gentile potrebbe essere utile.'}</p></div><div class="form-field"><label for="adviceInput">Indicazione personalizzata</label><textarea id="adviceInput">${escapeHtml(m?store.advice:'Ciao! Come sta andando il tuo percorso? Se ti va, aggiornami con qualche riga sul diario.')}</textarea></div><p class="form-hint">Suggerimenti educativi e di supporto. Le modifiche a farmaci o terapie competono sempre al medico curante.</p><div class="modal-actions"><button class="secondary-btn" id="messageClient">Apri messaggi</button><button class="primary-btn" id="saveAdvice">Salva e invia</button></div>`);$('#saveAdvice').onclick=()=>{if(m){store.advice=$('#adviceInput').value;save()}closeModal();toast(`Indicazione inviata a ${c.name}`)};$('#messageClient').onclick=()=>{closeModal();if(!m)toast(`Conversazione con ${c.name} pronta`);else{navigate('messaggi');$('#messageInput').focus()}}}
