$('#sendMessage').onclick=()=>{let input=$('#messageInput'),text=input.value.trim();if(!text)return toast('Scrivi un messaggio prima di inviarlo.');store.messages.push({text,date:new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})});save();let div=document.createElement('div');div.className='message-bubble user-message';let p=document.createElement('p');p.textContent=text;div.appendChild(p);let small=document.createElement('small');small.textContent=`Martina · ${store.messages.at(-1).date}`;div.appendChild(small);$('.message-compose').before(div);input.value='';toast('Messaggio inviato a Daniele.')};
