function updateAuthCopy(){if(!authInitialized)return;const en=language==='en';$('#authTitle').textContent=authMode==='login'?(en?'Welcome back.':'Bentornato.'):(en?'Create your account.':'Crea il tuo account.');$('#authIntro').textContent=authMode==='login'?(en?'Sign in to continue your Natural Sleep journey.':'Accedi per continuare il tuo percorso Sonno Naturale.'):(en?'Start your Natural Sleep journey with your coach.':'Inizia il tuo percorso Sonno Naturale con il tuo coach.');$('#authSubmit').textContent=authMode==='login'?(en?'Sign in':'Accedi'):(en?'Create account':'Crea account');$('#authNameField').hidden=authMode!=='signup';$('#authConsentField').hidden=authMode!=='signup';$('#authConsent').required=authMode==='signup';$('#authForm [name="password"]').autocomplete=authMode==='login'?'current-password':'new-password';$$('[data-auth-mode]').forEach(b=>b.classList.toggle('active',b.dataset.authMode===authMode));localize($('#authGate'))}
