function setSourceText(node,value){node.nodeValue=value;originalText.set(node,value)}
function setUserPresentation(user,profile){liveUser=user;liveProfile=profile;liveMode=true;const full=(profile.full_name||user.email?.split('@')[0]||'').trim(),first=full.split(/\s+/)[0]||'Cliente',initials=full.split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase()||(language==='en'?'NS':'SN');$$('.user-avatar').forEach(el=>{el.textContent=initials;el.title=language==='en'?'Sign out':'Esci dall’account';el.setAttribute('aria-label',el.title)});$$('.profile-avatar').forEach(el=>el.textContent=initials);const heading=$('.welcome-row h1');if(heading){const node=heading.firstChild;setSourceText(node,language==='en'?`Good morning, ${escapeHtml(first)}`:`Buongiorno, ${escapeHtml(first)}`);node.nodeValue=language==='en'?`Good morning, ${first}`:`Buongiorno, ${first}`}const name=$('.profile-main h2');if(name)name.textContent=full||first;const date=$('.profile-main p');if(date){date.textContent=(language==='en'?'Account created ':'Account creato ')+new Date(profile.created_at||Date.now()).toLocaleDateString(language==='en'?'en-GB':'it-IT')}const reminderRow=$$('.profile-row')[1];if(reminderRow)reminderRow.style.display='none';const privacyLink=$('.privacy-link');if(privacyLink)privacyLink.innerHTML=`<a href="https://sleepreset-daniele.netlify.app/privacy" target="_blank" rel="noopener">${language==='en'?'Read the privacy notice →':'Consulta l’informativa →'}</a>`;const switcher=$('#adminSwitch');switcher.hidden=true;$('#authGate').hidden=true;document.documentElement.lang=language==='en'?'en':'it';if(profile.role==='coach'){document.body.classList.add('admin-mode');$('#clientView').hidden=true;$('#adminView').hidden=false;switcher.setAttribute('aria-pressed','true');$$('.nav-link').forEach(b=>b.classList.remove('active'))}else{document.body.classList.remove('admin-mode');$('#adminView').hidden=true;$('#clientView').hidden=false;switcher.setAttribute('aria-pressed','false');navigate('oggi')}$('.topbar-context').lastChild.nodeValue=profile.role==='coach'?(language==='en'?' PRACTITIONER SPACE · LIVE':' SPAZIO PROFESSIONISTA · CONNESSO'):(language==='en'?' YOUR NATURAL SLEEP · LIVE':' IL TUO SONNO NATURALE · CONNESSO');if(profile.role!=='coach'){const pill=$('.hero-copy .pill');if(pill)pill.innerHTML=`<span class="live-pulse"></span>${language==='en'?'YOUR PERSONAL RESET PLAN':'IL TUO PIANO PERSONALIZZATO'}`;const heroText=$('.hero-copy>p');if(heroText)heroText.textContent=language==='en'?'Your coach will shape the next steps with you.':'Il tuo coach definirà con te i prossimi passi.'}}
async function loadLiveClientData(){if(!liveUser)return;const id=liveUser.id;const [goals,completions,diary,notes,assignments]=await Promise.all([SRDB.select('goals',{client_id:`eq.${id}`,order:'sort_order.asc'}),SRDB.select('goal_completions',{client_id:`eq.${id}`}),SRDB.select('sleep_entries',{client_id:`eq.${id}`,order:'night_date.desc',limit:'14'}),SRDB.select('coach_notes',{client_id:`eq.${id}`,visible_to_client:'eq.true',order:'created_at.desc',limit:'10'}),SRDB.select('coach_clients',{client_id:`eq.${id}`,select:'coach_id,client_id'})]);liveGoals=goals;liveCompletions=new Set(completions.map(x=>x.goal_id));liveDiary=diary;liveNotes=notes;liveCoachId=assignments[0]?.coach_id||null;const coachProfile=$$('.profile-row')[0]?.querySelector('strong');if(coachProfile)coachProfile.innerHTML=liveCoachId?(language==='en'?'Daniele Turriziani, pharmacist':'Daniele Turriziani, farmacista'):(language==='en'?'Not assigned yet':'Non ancora assegnato');renderTasks();renderWeeks();renderEntries();updateLiveClientDashboard();await renderLiveMessages(liveCoachId,'Daniele')}
function updateLiveClientDashboard(){const n=liveDiary.length,last=liveDiary[0];const pill=$('.hero-copy .pill');if(pill)pill.innerHTML=`<span class="live-pulse"></span>${language==='en'?'YOUR PERSONAL RESET PLAN':'IL TUO PIANO PERSONALIZZATO'}`;const heroText=$('.hero-copy>p');if(heroText)heroText.textContent=language==='en'?'Your coach will shape the next steps with you.':'Il tuo coach definirà con te i prossimi passi.';const firstLabel=$('.stats-grid article:nth-child(1) .stat-label'),firstFoot=$('.stats-grid article:nth-child(1) .stat-foot');if(firstLabel)firstLabel.textContent=language==='en'?'GOALS COMPLETED':'OBIETTIVI COMPLETATI';if(firstFoot)firstFoot.textContent=language==='en'?'Your assigned goals':'I tuoi obiettivi assegnati';const sparkline=$('.sparkline'),chartY=$('.chart-y');if(sparkline)sparkline.hidden=true;if(chartY)chartY.hidden=true;const label=$('.stats-grid article:nth-child(2) .stat-label'),value=$('.stats-grid article:nth-child(2) .stat-content>strong'),foot=$('.stats-grid article:nth-child(2) .stat-foot');if(label)label.textContent=language==='en'?'NIGHTS LOGGED':'NOTTI REGISTRATE';if(value)value.innerHTML=`${n} <small>${language==='en'?'entries':'notti'}</small>`;if(foot)foot.textContent=language==='en'?'From your sleep diary':'Dal tuo diario del sonno';const total=liveGoals.length,done=liveCompletions.size,pct=total?Math.round(done/total*100):0;const j=$('.journey-summary strong');if(j)j.innerHTML=`${done} <small>${language==='en'?`of ${total} goals completed`:`obiettivi completati su ${total}`}</small>`;const track=$('.journey-track span');if(track)track.style.width=`${pct}%`;const jp=$('.journey-percent');if(jp)jp.textContent=`${pct}%`;const day=$('.day-stamp');if(day){day.querySelector('span').textContent=language==='en'?'YOUR GOALS':'OBIETTIVI';day.querySelector('strong').textContent=String(total).padStart(2,'0');day.querySelector('small').textContent=language==='en'?'assigned':'assegnati'}const summary=$('.sleep-score');if(summary){if(!last){summary.innerHTML=`<p class="subheading">${language==='en'?'Your first sleep diary entry will appear here.':'Qui comparirà la tua prima notte registrata.'}</p>`;const vals=$$('.sleep-details strong');vals.forEach(x=>x.textContent='—');const d=$('.sleep-date');if(d)d.textContent='—'}else{summary.innerHTML=`<div class="score-ring"><div><strong>${durationLabel(last)}</strong><small>${language==='en'?'time in bed':'tempo a letto'}</small></div></div><div class="score-caption"><span class="score-dot"></span>${language==='en'?'One more night, one more insight':'Una notte in più, un dato in più'}</div>`;const values=$$('.sleep-details strong');if(values[0])values[0].textContent=`${last.sleep_latency_minutes??'—'} min`;if(values[1])values[1].textContent=`${last.awakenings??'—'} ${language==='en'?'times':'volte'}`;if(values[2])values[2].textContent=`${language==='en'?'Rated':'Valutata'} ${last.subjective_rating??'—'}/5`;const date=$('.sleep-date');if(date)date.textContent=dateLabel(last.night_date)}}const advice=$('.coach-stat-title');if(advice)advice.textContent=liveNotes[0]?(language==='en'?'New note from Daniele':'Nuovo consiglio di Daniele'):(language==='en'?'No new coach notes':'Nessun nuovo consiglio');const footNote=$('.coach-stat .stat-foot');if(footNote)footNote.textContent=liveNotes[0]?new Date(liveNotes[0].created_at).toLocaleDateString(language==='en'?'en-GB':'it-IT'):(language==='en'?'Your coach can add guidance':'Il coach potrà aggiungere indicazioni');const chart=$('.chart-main');if(chart)chart.innerHTML=`<div class="empty-chart">${language==='en'?'Your sleep trend will appear as you add diary entries.':'L’andamento comparirà man mano che aggiungi notti al diario.'}</div>`;const noteCard=$('.bottom-banner p');if(noteCard){noteCard.innerHTML=language==='en'?'<strong>Not every night will be the same.</strong><br>Your diary helps you and your coach notice patterns over time.':'<strong>Non tutte le notti saranno uguali.</strong><br>Il diario aiuta te e il tuo coach a osservare l’andamento nel tempo.'}}
async function loadLiveCoachData(){const links=await SRDB.select('coach_clients',{coach_id:`eq.${liveUser.id}`,select:'coach_id,client_id'});if(!links.length){liveClients=[];renderClients();updateCoachSummary();return}const ids=[...new Set(links.map(x=>x.client_id))],inside=`in.(${ids.join(',')})`;const [profiles,goals,completions,entries]=await Promise.all([SRDB.select('profiles',{id:inside}),SRDB.select('goals',{client_id:inside}),SRDB.select('goal_completions',{client_id:inside}),SRDB.select('sleep_entries',{client_id:inside,order:'night_date.desc',limit:String(ids.length*3)})]);liveClients=profiles.map(p=>{const gs=goals.filter(g=>g.client_id===p.id),done=completions.filter(c=>c.client_id===p.id).length,last=entries.find(e=>e.client_id===p.id);const name=p.full_name||'Cliente';return {id:p.id,name,initials:name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase(),phase:`${language==='en'?'Goals':'Obiettivi'} ${done}/${gs.length}`,progress:gs.length?Math.round(done/gs.length*100):0,activity:last?dateLabel(last.night_date):(language==='en'?'No diary yet':'Nessun diario'),status:gs.length?goalsStatus(done,gs.length): (language==='en'?'Needs goals':'Da avviare'),kind:gs.length?'good':'attention',color:''}});renderClients();updateCoachSummary()}
function goalsStatus(done,total){return done>=total&&total?(language==='en'?'On track':'In corso'):(language==='en'?'In progress':'In corso')}
function updateCoachSummary(){const kpis=$$('.admin-kpis article');if(kpis[0]){kpis[0].querySelector('strong').textContent=liveClients.length;kpis[0].querySelector('small').textContent=language==='en'?'Assigned to your account':'Assegnati al tuo account'}if(kpis[1]){kpis[1].querySelector('strong').textContent=liveClients.filter(c=>c.kind==='attention').length;kpis[1].querySelector('small').textContent=language==='en'?'Clients without goals assigned':'Clienti senza obiettivi assegnati'}if(kpis[2]){const total=liveClients.reduce((n,c)=>n+c.progress,0);kpis[2].querySelector('strong').innerHTML=`${liveClients.length?Math.round(total/liveClients.length):0}<small>%</small>`;kpis[2].querySelector('small').textContent=language==='en'?'Average goals completed':'Media obiettivi completati'}if(kpis[3]){kpis[3].querySelector('strong').textContent=liveClients.length;kpis[3].querySelector('span').textContent=language==='en'?'ASSIGNED CLIENTS':'CLIENTI ASSEGNATI';kpis[3].querySelector('small').textContent=language==='en'?'Currently linked to your account':'Collegati al tuo account'}const side=$('.admin-side');if(side)side.innerHTML=`<div class="attention-card"><div class="attention-top"><span class="attention-icon">✳</span><span class="attention-count">${liveClients.length} ${language==='en'?'CLIENTS':'CLIENTI'}</span></div><h3>${language==='en'?'Your client list':'I tuoi clienti'}</h3><p>${language==='en'?'Only accounts assigned to you are shown here.':'Qui compaiono solo gli account assegnati a te.'}</p><div class="safety-note"><span>♡</span><p>${language==='en'?'Use the diary as a basis for discussion, not as a diagnosis.':'Usa il diario come base di confronto, non come diagnosi.'}</p></div></div>`}
async function renderLiveMessages(peerId,peerName){livePeerId=peerId;livePeerName=peerName||'Daniele';const wrap=$('.message-wrap');if(!wrap)return;let rows=[];if(peerId){try{rows=await SRDB.select('messages',{or:`(sender_id.eq.${liveUser.id},recipient_id.eq.${liveUser.id})`,order:'created_at.asc',limit:'100'});rows=rows.filter(m=>(m.sender_id===peerId||m.recipient_id===peerId))}catch(err){toast((language==='en'?'Messages unavailable: ':'Messaggi non disponibili: ')+err.message)}}wrap.innerHTML=`<div class="message-date">${language==='en'?'SECURE CONVERSATION':'CONVERSAZIONE RISERVATA'}</div><div id="liveMessageList">${rows.map(m=>`<div class="message-bubble ${m.sender_id===liveUser.id?'user-message':'coach-message'}"><p>${escapeHtml(m.body)}</p><small>${m.sender_id===liveUser.id?(language==='en'?'You':'Tu'):escapeHtml(livePeerName)} · ${new Date(m.created_at).toLocaleString(language==='en'?'en-GB':'it-IT',{dateStyle:'short',timeStyle:'short'})}</small></div>`).join('')||`<p class="subheading">${language==='en'?'No messages yet.':'Nessun messaggio per ora.'}</p>`}</div><div class="message-compose"><textarea id="messageInput" placeholder="${language==='en'?'Write a message…':'Scrivi un messaggio…'}" rows="1" aria-label="${language==='en'?'Write a message':'Scrivi un messaggio'}" ${peerId?'':'disabled'}></textarea><button id="sendMessage" class="send-btn" aria-label="${language==='en'?'Send message':'Invia messaggio'}" ${peerId?'':'disabled'}>↑</button></div><p class="message-disclaimer">${language==='en'?'For urgent or medical concerns, contact your doctor or emergency services.':'Per urgenze o questioni mediche, contatta il tuo medico o i servizi di emergenza.'}</p>`;$('#sendMessage').onclick=sendLiveMessage}
async function sendLiveMessage(){const input=$('#messageInput'),body=input?.value.trim();if(!body)return;if(!livePeerId){toast(language==='en'?'No coach/client is linked yet.':'Non hai ancora un coach o cliente collegato.');return}try{await SRDB.insert('messages',{sender_id:liveUser.id,recipient_id:livePeerId,body});await renderLiveMessages(livePeerId,livePeerName);toast(language==='en'?'Message sent.':'Messaggio inviato.')}catch(e){toast((language==='en'?'Could not send message: ':'Invio non riuscito: ')+e.message)}}
async function openLiveClient(c){liveActiveClient=c;await renderLiveMessages(c.id,c.name);const goals=await SRDB.select('goals',{client_id:`eq.${c.id}`,order:'sort_order.asc'});const completions=await SRDB.select('goal_completions',{client_id:`eq.${c.id}`});const diary=await SRDB.select('sleep_entries',{client_id:`eq.${c.id}`,order:'night_date.desc',limit:'1'});showModal(`<p class="eyebrow">${language==='en'?'CLIENT PROGRAMME':'PERCORSO CLIENTE'} · ${escapeHtml(c.phase)}</p><div class="client-detail-head"><div class="avatar">${escapeHtml(c.initials)}</div><div><h2 id="modalTitle">${escapeHtml(c.name)}</h2><p>${language==='en'?'Last diary entry: ':'Ultima notte registrata: '}${diary[0]?dateLabel(diary[0].night_date):(language==='en'?'none yet':'nessuna')}</p></div></div><div class="detail-stats"><div class="detail-stat"><span>${language==='en'?'GOALS':'OBIETTIVI'}</span><strong>${completions.length}/${goals.length}</strong></div><div class="detail-stat"><span>${language==='en'?'PROGRESS':'PROGRESSO'}</span><strong>${goals.length?Math.round(completions.length/goals.length*100):0}%</strong></div><div class="detail-stat"><span>${language==='en'?'SLEEP ENTRIES':'NOTTI NEL DIARIO'}</span><strong>${diary.length?1:0}+</strong></div></div><div class="live-goal-list"><strong>${language==='en'?'ASSIGNED GOALS':'OBIETTIVI ASSEGNATI'}</strong>${goals.map(g=>`<div class="live-goal-row"><span>${escapeHtml(language==='en'?g.title_en:g.title_it)}</span><small>${completions.some(x=>x.goal_id===g.id)?'✓': '·'}</small></div>`).join('')||`<p class="form-hint">${language==='en'?'No goals assigned yet. Add the first one below.':'Nessun obiettivo assegnato. Aggiungi il primo qui sotto.'}</p>`}</div><details class="goal-editor"><summary>＋ ${language==='en'?'Assign a new goal':'Assegna un nuovo obiettivo'}</summary><form id="createGoalForm"><div class="form-grid"><div class="form-field"><label for="goalTitleIt">Titolo (IT)</label><input id="goalTitleIt" name="title_it" required maxlength="180"></div><div class="form-field"><label for="goalTitleEn">Title (EN)</label><input id="goalTitleEn" name="title_en" required maxlength="180"></div><div class="form-field"><label for="goalDescIt">Descrizione (IT)</label><textarea id="goalDescIt" name="description_it" maxlength="1000"></textarea></div><div class="form-field"><label for="goalDescEn">Description (EN)</label><textarea id="goalDescEn" name="description_en" maxlength="1000"></textarea></div><div class="form-field full"><label for="goalDue">${language==='en'?'Optional target date':'Data obiettivo (facoltativa)'}</label><input id="goalDue" name="due_date" type="date"></div></div><button class="primary-btn" type="submit">${language==='en'?'Save goal':'Salva obiettivo'}</button></form></details><div class="form-field"><label for="liveAdvice">${language==='en'?'Personalised supportive note':'Indicazione personalizzata di supporto'}</label><textarea id="liveAdvice" maxlength="3000" placeholder="${language==='en'?'Write a supportive note…':'Scrivi un consiglio di supporto…'}"></textarea></div><p class="form-hint">${language==='en'?'Educational support only. Medication and clinical decisions belong to the patient’s doctor.':'Supporto educativo. Le decisioni cliniche e sui farmaci spettano al medico curante.'}</p><div class="modal-actions"><button class="secondary-btn" id="liveMessageClient">${language==='en'?'Open conversation':'Apri conversazione'}</button><button class="primary-btn" id="saveLiveAdvice">${language==='en'?'Send note':'Invia indicazione'}</button></div>`);$('#createGoalForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await SRDB.insert('goals',{client_id:c.id,created_by:liveUser.id,title_it:String(f.get('title_it')).trim(),title_en:String(f.get('title_en')).trim(),description_it:String(f.get('description_it')||'').trim(),description_en:String(f.get('description_en')||'').trim(),due_date:f.get('due_date')||null,sort_order:goals.length});closeModal();await loadLiveCoachData();toast(language==='en'?'Goal assigned.':'Obiettivo assegnato.')}catch(err){toast((language==='en'?'Could not assign goal: ':'Impossibile assegnare l’obiettivo: ')+err.message)}});$('#saveLiveAdvice').onclick=async()=>{const body=$('#liveAdvice').value.trim();if(!body)return toast(language==='en'?'Write a note first.':'Scrivi prima un’indicazione.');try{await SRDB.insert('coach_notes',{client_id:c.id,author_id:liveUser.id,body,visible_to_client:true});closeModal();await loadLiveCoachData();toast(language==='en'?'Note sent to client.':'Indicazione inviata al cliente.')}catch(e){toast((language==='en'?'Could not save note: ':'Non sono riuscito a salvare: ')+e.message)}};$('#liveMessageClient').onclick=()=>window.openCoachConversation(c)}
async function activateAccount(user){const rows=await SRDB.select('profiles',{id:`eq.${user.id}`});if(!rows.length)throw new Error(language==='en'?'Profile not found. Confirm the schema migration and sign up again.':'Profilo non trovato. Verifica la migrazione dello schema e registra di nuovo l’account.');const profile=rows[0];let pending=null;try{pending=JSON.parse(localStorage.getItem('sr-pending-consent')||'null')}catch{}if(pending?.email===String(user.email||'').toLowerCase()){await SRDB.insert('privacy_consents',{client_id:user.id,policy_version:pending.version});localStorage.removeItem('sr-pending-consent')}if(profile.preferred_language)setLanguage(profile.preferred_language);setUserPresentation(user,profile);if(profile.role==='coach')await loadLiveCoachData();else await loadLiveClientData();$('#authGate').hidden=true}
async function initializeSupabaseAuth(){authInitialized=true;updateAuthCopy();$('#adminSwitch').hidden=true;$('#authSetup').hidden=false;$('#authSetup').textContent=language==='en'?'Supabase settings are in place. Sign in or create your account.':'Configurazione Supabase inserita. Accedi o crea il tuo account.';if(!SRDB.configured()){authError(language==='en'?'Supabase settings are incomplete.':'La configurazione Supabase è incompleta.');return}try{const user=await SRDB.currentUser();if(user)await activateAccount(user)}catch(e){$('#authGate').hidden=false;authError((language==='en'?'Could not load your account: ':'Non riesco a caricare l’account: ')+e.message)}}
$$('[data-auth-mode]').forEach(b=>b.addEventListener('click',()=>setAuthMode(b.dataset.authMode)));
$('#authForm').addEventListener('submit',async e=>{e.preventDefault();$('#authError').hidden=true;const form=new FormData(e.currentTarget),email=String(form.get('email')).trim(),password=String(form.get('password')),name=String(form.get('full_name')||'').trim();const submit=$('#authSubmit');submit.disabled=true;submit.textContent=language==='en'?'Please wait…':'Attendi…';try{if(authMode==='signup'){if(!name)throw new Error(language==='en'?'Enter your name.':'Inserisci il tuo nome.');if(!$('#authConsent').checked)throw new Error(language==='en'?'Please accept the privacy notice to create an account.':'Per creare l’account, leggi e accetta l’informativa privacy.');localStorage.setItem('sr-pending-consent',JSON.stringify({version:'sleep-reset-privacy-v1',email:email.toLowerCase()}));const result=await SRDB.signUp(email,password,name,language);if(!result.access_token){$('#authSetup').hidden=false;$('#authSetup').textContent=language==='en'?'Check your email to confirm your account, then come back here to sign in.':'Controlla la tua email per confermare l’account, poi torna qui per accedere.';setAuthMode('login');return}await activateAccount(result.user)}else{const user=await SRDB.signIn(email,password);await activateAccount(user)}}catch(err){$('#authGate').hidden=false;const translatedErrors={'Invalid login credentials':language==='en'?'Email or password is incorrect.':'Email o password non corretti.','Email not confirmed':language==='en'?'Confirm your email before signing in.':'Conferma la tua email prima di accedere.'};authError(translatedErrors[err.message]||err.message)}finally{submit.disabled=false;updateAuthCopy()}});
$('#userAvatar').addEventListener('click',async()=>{if(!liveMode)return;try{await SRDB.signOut()}finally{location.reload()}});$('#userAvatar').title='Esci dall’account';
$('#clientList').addEventListener('click',e=>{const row=e.target.closest('[data-client]');if(!row)return;if(liveMode){const c=liveClients[+row.dataset.client];if(c)openLiveClient(c)}else openClient(clients[+row.dataset.client])});
$('#openCoachNote').onclick=()=>{if(!liveMode){showModal(`<p class="eyebrow">UN MESSAGGIO PER TE · IERI</p><h2 id="modalTitle">Un consiglio di Daniele</h2><p>${escapeHtml(store.advice)}</p>`);return}const note=liveNotes[0];showModal(`<p class="eyebrow">${language==='en'?'NOTE FROM YOUR COACH':'NOTA DEL TUO COACH'}</p><h2 id="modalTitle">${language==='en'?'Personalised guidance':'Indicazione personalizzata'}</h2><div class="recommendation"><p>${note?escapeHtml(note.body):(language==='en'?'Your coach has not added a note yet.':'Il tuo coach non ha ancora aggiunto indicazioni.')}</p></div><p>${language==='en'?'For medical concerns, contact your doctor.':'Per questioni mediche, contatta il tuo medico.'}</p><div class="modal-actions"><button class="primary-btn" data-cancel>${language==='en'?'Close':'Chiudi'}</button></div>`)};
$('#sendMessage').onclick=()=>{if(liveMode){sendLiveMessage();return}const input=$('#messageInput'),text=input.value.trim();if(!text)return toast('Scrivi un messaggio prima di inviarlo.');store.messages.push({text,date:new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})});save();let div=document.createElement('div');div.className='message-bubble user-message';let p=document.createElement('p');p.textContent=text;div.appendChild(p);let small=document.createElement('small');small.textContent=`Martina · ${store.messages.at(-1).date}`;div.appendChild(small);$('.message-compose').before(div);input.value='';toast('Messaggio inviato a Daniele.')};
$('#addClientBtn').onclick=()=>showModal(`<p class="eyebrow">${language==='en'?'CLIENT ASSIGNMENT':'ASSEGNAZIONE CLIENTE'}</p><h2 id="modalTitle">${language==='en'?'Connect a client account':'Collega un account cliente'}</h2><p>${language==='en'?'For safety, account assignments are currently made in the Supabase SQL Editor after the client has registered and verified their email.':'Per sicurezza, al momento gli account si assegnano nel SQL Editor di Supabase dopo la registrazione e la verifica email del cliente.'}</p><div class="modal-actions"><button class="primary-btn" data-cancel>${language==='en'?'Understood':'Ho capito'}</button></div>`);
$('#clientFilter').onclick=()=>toast(language==='en'?'Showing all assigned clients.':'Stai visualizzando tutti i clienti assegnati.');
$('#editProfile').onclick=async()=>{if(!liveMode)return toast('La modifica del profilo sarà disponibile nel tuo spazio personale.');const name=prompt(language==='en'?'Update your display name':'Aggiorna il tuo nome',liveProfile.full_name);if(name===null)return;try{await SRDB.update('profiles',{id:`eq.${liveUser.id}`},{full_name:name});liveProfile.full_name=name;setUserPresentation(liveUser,liveProfile);toast(language==='en'?'Profile updated.':'Profilo aggiornato.')}catch(e){toast(e.message)}};
$$('[data-admin-action]').forEach(b=>b.onclick=()=>toast('Nessun altro promemoria urgente.'));
$$('.toggle').forEach(b=>b.onclick=()=>{b.classList.toggle('on');b.setAttribute('aria-label',b.classList.contains('on')?'Disattiva promemoria':'Attiva promemoria');toast(b.classList.contains('on')?'Promemoria attivato.':'Promemoria disattivato.')});
window.SleepResetUI={showModal,toast};
const priorSetLanguage=setLanguage;
setLanguage=function(next){priorSetLanguage(next);if(authInitialized)updateAuthCopy();if(liveMode){const full=(liveProfile.full_name||liveUser.email?.split('@')[0]||'').trim(),first=full.split(/\s+/)[0]||'Cliente',heading=$('.welcome-row h1');if(heading?.firstChild){const greeting=language==='en'?`Good morning, ${first}`:`Buongiorno, ${first}`;setSourceText(heading.firstChild,greeting)}const context=$('.topbar-context');if(context)context.lastChild.nodeValue=liveProfile.role==='coach'?(language==='en'?' PRACTITIONER SPACE · LIVE':' SPAZIO PROFESSIONISTA · CONNESSO'):(language==='en'?' YOUR NATURAL SLEEP · LIVE':' IL TUO SONNO NATURALE · CONNESSO');renderTasks();renderWeeks();renderEntries();updateLiveClientDashboard();const privacy=$('.privacy-link');if(privacy)privacy.innerHTML=`<a href="https://sleepreset-daniele.netlify.app/privacy" target="_blank" rel="noopener">${language==='en'?'Read the privacy notice →':'Consulta l’informativa →'}</a>`;$$('.user-avatar').forEach(el=>{el.title=language==='en'?'Sign out':'Esci dall’account';el.setAttribute('aria-label',el.title)});SRDB.update('profiles',{id:`eq.${liveUser.id}`},{preferred_language:language}).catch(()=>{});if(liveProfile.role==='coach')loadLiveCoachData().catch(e=>toast(e.message));else if(livePeerId)renderLiveMessages(livePeerId,livePeerName)}};
renderTasks();renderWeeks();renderEntries();renderClients();
$('#languageToggle').addEventListener('click',()=>setLanguage(language==='it'?'en':'it'));$('#authLanguage').addEventListener('click',()=>setLanguage(language==='it'?'en':'it'));setLanguage(language);
initializeSupabaseAuth();
if('serviceWorker' in navigator && location.protocol.startsWith('http'))navigator.serviceWorker.register(new URL('sw.js',document.baseURI)).catch(()=>{});
